"""Tool response helpers."""

from __future__ import annotations

import base64
import json
from dataclasses import dataclass, field
from typing import Any

from mcp.types import CallToolResult, ImageContent, TextContent


def json_text(payload: dict[str, Any]) -> str:
    """Serialize a payload in a stable, agent-friendly format."""

    return json.dumps(payload, ensure_ascii=False, sort_keys=True)


@dataclass(frozen=True)
class ImageArtifact:
    """Binary image content returned by a tool."""

    camera: str
    data: bytes
    mime_type: str


@dataclass(frozen=True)
class ToolResponse:
    """Normalized response before converting to MCP content blocks."""

    payload: dict[str, Any]
    images: list[ImageArtifact] = field(default_factory=list)
    text: str | None = None
    is_error: bool = False


def to_call_tool_result(response: ToolResponse) -> CallToolResult:
    """Convert a normalized response into an MCP CallToolResult."""

    content: list[TextContent | ImageContent] = []
    if response.text is not None:
        content.append(TextContent(type="text", text=response.text))
    elif not response.images:
        content.append(TextContent(type="text", text=json_text(response.payload)))

    for image in response.images:
        content.append(
            ImageContent(
                type="image",
                data=base64.b64encode(image.data).decode("ascii"),
                mimeType=image.mime_type,
            )
        )

    return CallToolResult(
        content=content,
        structuredContent=response.payload,
        isError=response.is_error,
    )
